const D = { block:.5, shimmer:.5, energy:.6, speed:1, density:.5, hue:210, scale:1, x:.5, y:.5, style:'mosaic', act:'pump', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), lrp=(a,b,t)=>a+(b-a)*t, md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const st=P.style, act=P.act, HUE=md(P.hue,360);
const cnv=drawingContext.canvas;
const oldOp=drawingContext.globalCompositeOperation;
const perBlock=(st==='crt'||st==='ascii'||st==='dither'||st==='diamond');

// fixed small sampling buffer
const BW=248,BH=160;
if(!S.buf){ S.buf=createGraphics(BW,BH); S.buf.pixelDensity(1); }

// ---- block size: base param + dramaturgy pump (big=low intensity) ----
let pump=1;
if(act==='pump'){ pump=1 + (1-clp(K.intensity+A.bass*0.4,0,1))*0.7 + K.pulse*0.25*P.energy; }
else if(act==='dissolve'){ const ph=md(K.section,4)/4 + K.cyc*0.25; pump=lrp(2.4,0.5,clp(ph,0,1)); } // huge -> fine over sections
else { pump=1 + 0.5*(0.5+0.5*Math.sin(K.t*0.09)); } // drift
const blockPx=clp(lrp(u*0.02,u*0.19,clp(P.block,0,1))*pump, u*0.012, u*0.5);
let bx=Math.max(4,Math.round(W/blockPx)), by=Math.max(3,Math.round(Hh/blockPx));
if(perBlock){ // cap per-block iteration cost
  const capX=44, capY=30; bx=Math.min(bx,capX); by=Math.min(by,capY);
}else{ bx=Math.min(bx,BW); by=Math.min(by,BH); }
const cw=W/bx, ch=Hh/by;

// ---- downsample the composited frame (averaging), crawl the sample origin so real content mosaics move ----
const dxo=Math.sin(K.t*0.11)*cw*0.4, dyo=Math.cos(K.t*0.083)*ch*0.4;
S.buf.drawingContext.imageSmoothingEnabled=true;
try{ S.buf.drawingContext.clearRect(0,0,BW,BH); S.buf.drawingContext.drawImage(cnv, dxo,dyo,W,Hh, 0,0,bx,by); }catch(e){}

const sh=clp(P.shimmer,0,1);
const tw=Math.floor(K.t*(3+6*P.speed)); // shimmer time-step; never re-phases at 8s

if(!perBlock){
  // ---- fast path: blocky upscale of the real frame ----
  drawingContext.imageSmoothingEnabled=false;
  try{ drawingContext.drawImage(S.buf, 0,0,bx,by, 0,0,W,Hh); }catch(e){}
  drawingContext.imageSmoothingEnabled=true;
  // faint seam grid (crawls) + coarse shimmer overlay (motion floor on flat frames)
  blendMode(MULTIPLY); stroke(0,0,0,18); strokeWeight(1); noFill();
  const gx=md(K.t*8,cw); for(let x=gx;x<W;x+=cw) line(x,0,x,Hh);
  const gy=md(K.t*6,ch); for(let y=gy;y<Hh;y+=ch) line(0,y,W,y);
  blendMode(BLEND);
}else{
  // ---- per-block artistic re-render ----
  let px; try{ px=S.buf.drawingContext.getImageData(0,0,bx,by).data; }catch(e){ px=null; }
  const val=(i,j)=>{ if(!px) return 40; const k=(j*bx+i)*4; return (px[k]*0.3+px[k+1]*0.59+px[k+2]*0.11)/255*100; };
  const hueAt=(i,j)=>{ if(!px) return HUE; const k=(j*bx+i)*4, r=px[k]/255,g=px[k+1]/255,b=px[k+2]/255; const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn; if(d<0.02) return HUE; let h=0; if(mx===r)h=((g-b)/d)%6; else if(mx===g)h=(b-r)/d+2; else h=(r-g)/d+4; return md(h*60,360); };
  noStroke();
  for(let j=0;j<by;j++)for(let i=0;i<bx;i++){
    const sm=(fr(i*3.1+j*7.7)+0.0, (Math.sin((i*1.3+j*2.1)+K.t*(0.8+P.speed))*0.5+0.5)); // per-cell shimmer wave
    let v=clp(val(i,j)/100 + (sm-0.5)*sh*0.55 + K.pulse*0.12*P.energy, 0.04, 1)*100;
    const cx=i*cw, cy=j*ch, hh=(st==='crt')?hueAt(i,j):HUE;
    if(st==='ascii'){
      const g=v/100; fill(HUE, 30+40*g, 40+55*g, 90);
      const r=Math.max(1,(cw*0.92)*g);
      ellipse(cx+cw*0.5, cy+ch*0.5, r, r);
    }else if(st==='crt'){
      const bw3=cw/3;
      fill(0,90,100, v*0.9); rect(cx,cy,bw3,ch*0.92);
      fill(120,90,100, v*0.9); rect(cx+bw3,cy,bw3,ch*0.92);
      fill(240,90,100, v*0.9); rect(cx+bw3*2,cy,bw3,ch*0.92);
    }else if(st==='dither'){
      const lv=Math.round(v/100*3)/3; const bay=((i&1)^(j&1)); const th=bay?0.12:-0.12;
      const on=(lv+th)>0.4;
      fill(HUE, 55, on?85:18, 95); rect(cx,cy,cw*0.96,ch*0.96);
    }else{ // diamond
      push(); translate(cx+cw*0.5, cy+ch*0.5); rotate(Math.PI/4);
      fill(hh, 55, v, 92); const s=cw*0.62*(0.5+v/100*0.7); rect(-s/2,-s/2,s,s); pop();
    }
  }
}

// ---- coarse shimmer cells: always-moving self-generated motion (carries gate on flat beds) ----
{
  const CX=22, CY=13, cwc=W/CX, chc=Hh/CY;
  blendMode(SCREEN); noStroke();
  for(let j=0;j<CY;j++)for(let i=0;i<CX;i++){
    const f=fr(i*5.3+j*9.1);
    const s=Math.sin((i*0.9+j*1.7)+K.t*(1.1+P.speed)+f*6.28)*0.5+0.5;
    const a=(2.5+9*sh)*s*(0.5+0.5*K.intensity);
    if(a<0.6) continue;
    fill(md(HUE+f*70,360), 40, 100, a);
    rect(i*cwc, j*chc, cwc, chc);
  }
  blendMode(BLEND);
}

// ---- rolling scanline band for extra life ----
{
  blendMode(MULTIPLY); noStroke();
  const by2=md(K.t*u*0.16,Hh*1.2)-Hh*0.1;
  fill(0,0,0,20); rect(0,by2,W,u*0.04);
  blendMode(BLEND);
}

